//! Acceptance tests for mini-redis. They build and spawn YOUR binary on a free port and speak RESP
//! to it over TCP — exactly what redis-cli does. Do not edit this file; make it pass.

use std::io::{BufRead, BufReader, Read, Write};
use std::net::{TcpListener, TcpStream};
use std::process::{Child, Command, Stdio};
use std::time::{Duration, Instant};

struct Server { child: Child, port: u16 }

impl Server {
    fn start(extra: &[&str]) -> Server {
        let port = TcpListener::bind("127.0.0.1:0").unwrap().local_addr().unwrap().port();
        let child = Command::new(env!("CARGO_BIN_EXE_mini-redis"))
            .arg("--port").arg(port.to_string()).args(extra)
            .stdout(Stdio::null()).stderr(Stdio::inherit())
            .spawn().expect("spawn mini-redis binary");
        let s = Server { child, port };
        let t = Instant::now();
        while TcpStream::connect(("127.0.0.1", port)).is_err() {
            assert!(t.elapsed() < Duration::from_secs(10), "server did not start listening on {port} within 10s");
            std::thread::sleep(Duration::from_millis(50));
        }
        s
    }
    fn client(&self) -> Client { Client::connect(self.port) }
}
impl Drop for Server { fn drop(&mut self) { let _ = self.child.kill(); let _ = self.child.wait(); } }

struct Client { r: BufReader<TcpStream>, w: TcpStream }

#[derive(Debug, PartialEq, Clone)]
enum Reply { Status(String), Error(String), Int(i64), Bulk(Option<String>), Array(Option<Vec<Reply>>) }

impl Client {
    fn connect(port: u16) -> Client {
        let s = TcpStream::connect(("127.0.0.1", port)).unwrap();
        s.set_read_timeout(Some(Duration::from_secs(5))).unwrap();
        Client { r: BufReader::new(s.try_clone().unwrap()), w: s }
    }
    fn send_raw(&mut self, bytes: &[u8]) { self.w.write_all(bytes).unwrap(); self.w.flush().unwrap(); }
    fn encode(args: &[&str]) -> Vec<u8> {
        let mut v = format!("*{}\r\n", args.len()).into_bytes();
        for a in args { v.extend(format!("${}\r\n{}\r\n", a.len(), a).into_bytes()); }
        v
    }
    fn cmd(&mut self, args: &[&str]) -> Reply { self.send_raw(&Self::encode(args)); self.read_reply() }
    fn read_line(&mut self) -> String {
        let mut l = String::new();
        self.r.read_line(&mut l).expect("read line");
        assert!(l.ends_with("\r\n"), "line not CRLF-terminated: {l:?}");
        l.truncate(l.len() - 2);
        l
    }
    fn read_reply(&mut self) -> Reply {
        let line = self.read_line();
        let (t, rest) = line.split_at(1);
        match t {
            "+" => Reply::Status(rest.to_string()),
            "-" => Reply::Error(rest.to_string()),
            ":" => Reply::Int(rest.parse().unwrap()),
            "$" => {
                let n: i64 = rest.parse().unwrap();
                if n < 0 { return Reply::Bulk(None); }
                let mut buf = vec![0u8; n as usize + 2];
                self.r.read_exact(&mut buf).unwrap();
                Reply::Bulk(Some(String::from_utf8_lossy(&buf[..n as usize]).to_string()))
            }
            "*" => {
                let n: i64 = rest.parse().unwrap();
                if n < 0 { return Reply::Array(None); }
                Reply::Array(Some((0..n).map(|_| self.read_reply()).collect()))
            }
            _ => panic!("bad RESP type byte in {line:?}"),
        }
    }
}

fn status(s: &str) -> Reply { Reply::Status(s.into()) }
fn bulk(s: &str) -> Reply { Reply::Bulk(Some(s.into())) }

#[test]
fn ping_echo_and_handshake() {
    let srv = Server::start(&[]);
    let mut c = srv.client();
    assert_eq!(c.cmd(&["PING"]), status("PONG"));
    assert_eq!(c.cmd(&["ping"]), status("PONG"), "commands are case-insensitive");
    assert_eq!(c.cmd(&["PING", "hi"]), bulk("hi"));
    assert_eq!(c.cmd(&["ECHO", "hello world"]), bulk("hello world"));
    assert_eq!(c.cmd(&["COMMAND", "DOCS"]), status("OK"));
    assert_eq!(c.cmd(&["CONFIG", "GET", "save"]), Reply::Array(Some(vec![])));
    // inline command, as redis-cli sends interactively
    c.send_raw(b"PING\r\n");
    assert_eq!(c.read_reply(), status("PONG"));
}

#[test]
fn basic() {
    let srv = Server::start(&[]);
    let mut c = srv.client();
    assert_eq!(c.cmd(&["GET", "missing"]), Reply::Bulk(None));
    assert_eq!(c.cmd(&["SET", "k", "v"]), status("OK"));
    assert_eq!(c.cmd(&["GET", "k"]), bulk("v"));
    assert_eq!(c.cmd(&["SET", "k", "v2"]), status("OK"));
    assert_eq!(c.cmd(&["GET", "k"]), bulk("v2"));
    assert_eq!(c.cmd(&["EXISTS", "k", "nope"]), Reply::Int(1));
    assert_eq!(c.cmd(&["DBSIZE"]), Reply::Int(1));
    assert_eq!(c.cmd(&["DEL", "k", "nope"]), Reply::Int(1));
    assert_eq!(c.cmd(&["GET", "k"]), Reply::Bulk(None));
    c.cmd(&["SET", "a", "1"]); c.cmd(&["SET", "b", "2"]);
    assert_eq!(c.cmd(&["FLUSHALL"]), status("OK"));
    assert_eq!(c.cmd(&["DBSIZE"]), Reply::Int(0));
    // binary-safe values with spaces and CRLF inside
    assert_eq!(c.cmd(&["SET", "bin", "a b\r\nc"]), status("OK"));
    assert_eq!(c.cmd(&["GET", "bin"]), bulk("a b\r\nc"));
}

#[test]
fn errors() {
    let srv = Server::start(&[]);
    let mut c = srv.client();
    match c.cmd(&["NOPE"]) { Reply::Error(e) => assert!(e.contains("unknown command"), "{e}"), r => panic!("{r:?}") }
    match c.cmd(&["GET"]) { Reply::Error(e) => assert!(e.contains("wrong number of arguments"), "{e}"), r => panic!("{r:?}") }
    match c.cmd(&["SET", "onlykey"]) { Reply::Error(e) => assert!(e.contains("wrong number of arguments"), "{e}"), r => panic!("{r:?}") }
    // garbage must not kill the server
    let mut g = srv.client();
    g.send_raw(b"\x00\x01\x02garbage\r\n");
    let _ = g.r.read_line(&mut String::new());   // error reply or EOF — either is fine
    let mut c2 = srv.client();
    assert_eq!(c2.cmd(&["PING"]), status("PONG"), "server must survive a garbage client");
}

#[test]
fn incr() {
    let srv = Server::start(&[]);
    let mut c = srv.client();
    assert_eq!(c.cmd(&["INCR", "n"]), Reply::Int(1));
    assert_eq!(c.cmd(&["INCR", "n"]), Reply::Int(2));
    assert_eq!(c.cmd(&["GET", "n"]), bulk("2"));
    c.cmd(&["SET", "n", "40"]);
    assert_eq!(c.cmd(&["INCR", "n"]), Reply::Int(41));
    c.cmd(&["SET", "s", "abc"]);
    match c.cmd(&["INCR", "s"]) { Reply::Error(e) => assert!(e.contains("not an integer"), "{e}"), r => panic!("{r:?}") }
}

#[test]
fn ttl_passive() {
    let srv = Server::start(&[]);
    let mut c = srv.client();
    assert_eq!(c.cmd(&["SET", "t", "1", "PX", "150"]), status("OK"));
    let ttl = c.cmd(&["TTL", "t"]);
    assert!(matches!(ttl, Reply::Int(0) | Reply::Int(1)), "TTL rounds up seconds: {ttl:?}");
    assert_eq!(c.cmd(&["GET", "t"]), bulk("1"));
    std::thread::sleep(Duration::from_millis(250));
    assert_eq!(c.cmd(&["GET", "t"]), Reply::Bulk(None), "expired key must read as null");
    assert_eq!(c.cmd(&["TTL", "t"]), Reply::Int(-2));
    c.cmd(&["SET", "p", "1"]);
    assert_eq!(c.cmd(&["TTL", "p"]), Reply::Int(-1));
    assert_eq!(c.cmd(&["EXPIRE", "p", "10"]), Reply::Int(1));
    let ttl = c.cmd(&["TTL", "p"]);
    assert!(matches!(ttl, Reply::Int(9) | Reply::Int(10)), "{ttl:?}");
    assert_eq!(c.cmd(&["EXPIRE", "nope", "10"]), Reply::Int(0));
    assert_eq!(c.cmd(&["SET", "e", "1", "EX", "1"]), status("OK"));
    let ttl = c.cmd(&["TTL", "e"]);
    assert_eq!(ttl, Reply::Int(1));
}

#[test]
fn ttl_active() {
    let srv = Server::start(&[]);
    let mut c = srv.client();
    for i in 0..200 { c.cmd(&["SET", &format!("k{i}"), "v", "PX", "100"]); }
    c.cmd(&["SET", "keep", "v"]);
    assert_eq!(c.cmd(&["DBSIZE"]), Reply::Int(201));
    // never read the expiring keys; a background sweep must remove them
    let t = Instant::now();
    loop {
        if c.cmd(&["DBSIZE"]) == Reply::Int(1) { break; }
        assert!(t.elapsed() < Duration::from_secs(2), "active expiry did not sweep 200 expired keys within 2s");
        std::thread::sleep(Duration::from_millis(50));
    }
}

#[test]
fn lru() {
    let srv = Server::start(&["--max-keys", "3"]);
    let mut c = srv.client();
    c.cmd(&["SET", "a", "1"]); c.cmd(&["SET", "b", "2"]); c.cmd(&["SET", "c", "3"]);
    assert_eq!(c.cmd(&["GET", "a"]), bulk("1"));      // touch a → b is now the least recently used
    c.cmd(&["SET", "d", "4"]);                          // evicts b
    assert_eq!(c.cmd(&["GET", "b"]), Reply::Bulk(None), "b was LRU and must be evicted");
    assert_eq!(c.cmd(&["GET", "a"]), bulk("1"));
    assert_eq!(c.cmd(&["GET", "c"]), bulk("3"));
    assert_eq!(c.cmd(&["GET", "d"]), bulk("4"));
    assert_eq!(c.cmd(&["DBSIZE"]), Reply::Int(3));
    c.cmd(&["SET", "a", "9"]);                          // overwrite must not grow or evict
    assert_eq!(c.cmd(&["DBSIZE"]), Reply::Int(3));
}

#[test]
fn pipeline() {
    let srv = Server::start(&[]);
    let mut c = srv.client();
    let mut batch = Vec::new();
    for i in 0..1000 { batch.extend(Client::encode(&["SET", &format!("p{i}"), &i.to_string()])); }
    for i in 0..1000 { batch.extend(Client::encode(&["GET", &format!("p{i}")])); }
    c.send_raw(&batch);
    for _ in 0..1000 { assert_eq!(c.read_reply(), status("OK")); }
    for i in 0..1000 { assert_eq!(c.read_reply(), bulk(&i.to_string()), "pipelined replies must be in order"); }
}

#[test]
fn split_frames() {
    let srv = Server::start(&[]);
    let mut c = srv.client();
    let full = Client::encode(&["SET", "split", "value"]);
    for chunk in full.chunks(3) {
        c.send_raw(chunk);
        std::thread::sleep(Duration::from_millis(5));
    }
    assert_eq!(c.read_reply(), status("OK"));
    assert_eq!(c.cmd(&["GET", "split"]), bulk("value"));
}

#[test]
fn concurrent_clients() {
    let srv = Server::start(&[]);
    let port = srv.port;
    let handles: Vec<_> = (0..50).map(|_| std::thread::spawn(move || {
        let mut c = Client::connect(port);
        for _ in 0..100 { match c.cmd(&["INCR", "counter"]) { Reply::Int(_) => {}, r => panic!("{r:?}") } }
    })).collect();
    for h in handles { h.join().unwrap(); }
    let mut c = srv.client();
    assert_eq!(c.cmd(&["GET", "counter"]), bulk("5000"));
}
